-- Minimal pre-migration schema for regression tests, not a production baseline.
create role anon; create role authenticated; create role service_role bypassrls;
create schema auth; create schema private;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
grant usage on schema public,auth,private to authenticated,anon,service_role;
create table public.profiles(id uuid primary key,role text,first_name text,last_name text,birth_date date,phone text,email text,is_active boolean default true,must_change_password boolean default false,register_date date default current_date);
create table public.trainer_clients(id uuid default gen_random_uuid() primary key,trainer_id uuid references profiles,client_id uuid references profiles,is_active boolean default true);
create table public.routines(id uuid default gen_random_uuid() primary key,client_id uuid references profiles,trainer_id uuid references profiles,name text,status text,is_active boolean,start_date date,end_date date);
create table public.workout_sessions(id uuid default gen_random_uuid() primary key,client_id uuid references profiles,date date);
create table public.body_compositions(id uuid default gen_random_uuid() primary key,client_id uuid references profiles,date date,weight numeric,fat_percentage numeric);
create table public.health_screenings(id uuid default gen_random_uuid() primary key,client_id uuid references profiles,version integer,has_critical_risk boolean,payload_ciphertext text,encryption_iv text,encryption_tag text,encryption_key_version smallint,content_hash text,consent_version text,privacy_notice_version text,submitted_at timestamptz,expires_at timestamptz,unique(client_id,version));
create table public.health_screening_reviews(id uuid default gen_random_uuid() primary key,screening_id uuid references health_screenings,trainer_id uuid references profiles,decision text check(decision in ('cleared','cleared_with_restrictions','medical_clearance_required')),notes_ciphertext text,encryption_iv text,encryption_tag text,encryption_key_version smallint,reviewed_at timestamptz default now());
create table public.health_documents(id uuid default gen_random_uuid() primary key,client_id uuid references profiles,screening_id uuid references health_screenings,uploaded_by uuid references profiles,storage_path text unique);
create table public.health_audit_events(client_id uuid,screening_id uuid,actor_id uuid,action text);
create table public.exercises(id uuid default gen_random_uuid() primary key,name text,image_url text,video_url text,created_by uuid references profiles);
create table public.body_zones(id uuid primary key);
create table public.equipment(id uuid primary key);
create table public.exercise_body_zones(exercise_id uuid references exercises,body_zone_id uuid references body_zones,primary key(exercise_id,body_zone_id));
create table public.exercise_equipment(exercise_id uuid references exercises,equipment_id uuid references equipment,primary key(exercise_id,equipment_id));
grant all on all tables in schema public to authenticated,service_role;
alter table profiles enable row level security;
create policy own_profile on profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
alter table exercise_body_zones enable row level security;
alter table exercise_equipment enable row level security;
create policy read_zones on exercise_body_zones for select to authenticated using(true);
create policy read_equipment on exercise_equipment for select to authenticated using(true);
create policy write_zones on exercise_body_zones for insert to authenticated with check(exists(select 1 from profiles where id=auth.uid() and role='trainer'));
create policy write_equipment on exercise_equipment for insert to authenticated with check(exists(select 1 from profiles where id=auth.uid() and role='trainer'));
